 // All three conditions matter; dropping the registry check spins the tool loop.

 const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
@@ -19,3 +20,26 @@
   it('stops when the model finished for a reason other than tool use', () => {
     expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
   });
 });
+
+describe('aggregateUsage', () => {
+  it('preserves undefined when neither round reports usage', () => {
+    expect(aggregateUsage(undefined, undefined)).toBeUndefined();
+  });
+
+  it('adopts round usage when total is currently undefined', () => {
+    const round: UsageMetadata = {inputTokens: 2, outputTokens: 3, totalTokens: 5};
+    expect(aggregateUsage(undefined, round)).toEqual(round);
+  });
+
+  it('ignores undefined round usage to preserve existing total', () => {
+    const total: TurnUsage = {inputTokens: 2, outputTokens: 3, totalTokens: 5};
+    expect(aggregateUsage(total, undefined)).toEqual(total);
+  });
+
+  it('sums each field when both total and round report usage', () => {
+    const total: TurnUsage = {inputTokens: 2, outputTokens: 3, totalTokens: 5};
+    const round: UsageMetadata = {inputTokens: 10, outputTokens: 20, totalTokens: 30};
+    expect(aggregateUsage(total, round)).toEqual({
+      inputTokens: 12,
+      outputTokens: 23,
+      totalTokens: 35,
+    });
+  });
+});
EOF
patch -p0 < orchestratorHelpers.test.patch

